def retry(max_attempts=3):
    def decorator(func):
        def wrapper(*args, **kwargs):
            attempt = 0
            while attempt < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempt += 1
                    if attempt < max_attempts:
                        print(f"Attempt {attempt} failed with {e}, retrying...")
                    else:
                        raise  # Explicitly re-raise the exception after all attempts
        return wrapper
    return decorator

# Usage example
@retry(max_attempts=3)
def risky_function():
    import random
